const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wolfVolcano = ee.Geometry.Point([-91.345, -0.023]);
  const aoi = wolfVolcano.buffer(5000); // 5km buffer around the volcano

  const date1_start = '2022-01-06';
  const date1_end = '2022-01-07';
  const date2_start = '2022-01-07';
  const date2_end = '2022-01-08';

  const collectionId = 'NOAA/VIIRS/DNB/DAILY_V1/VNP46A2';
  const bandName = 'DNB_At_Sensor_Radiance_500m';

  // Function to acquire, process, and calculate mean radiance for a given date
  function getMeanRadiance(dateStart, dateEnd, aoi) {
    const date = ee.Date(dateStart).format('YYYY-MM-dd').getInfo();
    const imageCollection = ee.ImageCollection(collectionId)
      .filterBounds(aoi)
      .filterDate(dateStart, dateEnd);

    const size = imageCollection.size().getInfo();
    if (size === 0) {
      console.log(`Image Collection on ${date}: 0`);
      return null;
    }

    // Create a composite from the collection and select bands
    const image = imageCollection.median();
    const radianceBand = image.select(bandName);
    const qualityBand = image.select('QF_Cloud_Mask');

    // Mask out cloudy pixels. Bit 0 of QF_Cloud_Mask should be 0 for "Confident Clear".
    // Left shift 1 by 0 bits to create a mask for the first bit, and check if it's 0.
    const cloudFreeMask = qualityBand.bitwiseAnd(1 << 0).eq(0);
    const maskedRadiance = radianceBand.updateMask(cloudFreeMask);

    const scale = 1000;

    // Check for valid pixels
    const pixelCount = maskedRadiance.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    }).get(bandName).getInfo();

    if (pixelCount === 0 || pixelCount === null) {
      console.log(`Image on ${date}: Found but 0 valid (cloud-free) pixels.`);
      return { radiance: undefined, pixels: 0 };
    }

    // Calculate mean radiance
    const stats = maskedRadiance.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    });

    const meanRadiance = stats.get(bandName).getInfo();

    return { radiance: meanRadiance, pixels: pixelCount };
  }

  // 2. Data Acquisition & Processing
  const result1 = getMeanRadiance(date1_start, date1_end, aoi);
  const result2 = getMeanRadiance(date2_start, date2_end, aoi);

  // 3. Validation & Final Answer
  if (result1 === null || result2 === null) {
    console.log("Evidence: No image found for one or both dates.");
    console.log('B');
    return;
  }

  if (result1.pixels === 0 || result2.pixels === 0) {
      console.log(`Jan 6, 2022 Radiance: - | Pixels: ${result1.pixels}`);
      console.log(`Jan 7, 2022 Radiance: - | Pixels: ${result2.pixels}`);
      console.log("Evidence: No cloud-free pixels to analyze for at least one date.");
      console.log('B');
      return;
  }

  const radiance1 = result1.radiance;
  const radiance2 = result2.radiance;

  console.log(`Jan 6, 2022 Radiance: ${radiance1.toFixed(2)} | Pixels: ${result1.pixels}`);
  console.log(`Jan 7, 2022 Radiance: ${radiance2.toFixed(2)} | Pixels: ${result2.pixels}`);

  if (radiance1 === null || radiance2 === null) {
    console.log("Evidence: Calculation failed for one or both dates.");
    console.log('C3');
    return;
  }

  if (radiance2 > radiance1) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("Error running analysis: ", err);
    console.log('D');
});
